use verus::prelude::*;

#[requires(true)]
#[ensures(
    // Case 1: no padding needed ⇒ result is exactly the original
    orig.len() >= (width as usize) ==>
        result == orig,

    // Case 2: padding needed ⇒
    // 1) the result has length exactly `width`
    // 2) the first `width - orig.len()` entries are `fillchar`
    // 3) the remaining entries reproduce `orig`
    orig.len() < (width as usize) ==>
        result.len() == (width as usize) &&
        forall(|i: usize| i < (width as usize - orig.len()) ==>
            result[i] == fillchar) &&
        forall(|i: usize| (width as usize - orig.len()) <= i && i < (width as usize) ==>
            result[i] == orig[i - (width as usize - orig.len())])
)]
fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let target = width as usize;
    let orig_len = orig.len();

    if orig_len >= target {
        // If the original is already as long or longer, return it unchanged.
        orig
    } else {
        // Otherwise, build a new vector with leading fillchars.
        let mut res = Vec::with_capacity(target);
        // After this extend, res.len() == target - orig_len
        res.extend(std::iter::repeat(fillchar).take(target - orig_len));
        // After this extend, res.len() == target
        res.extend(orig);
        res
    }
}

